// PBR materials, lighting, sky and environment for "How It's Built" (v2 kit).
// Textures live in public/tex/<name>/{albedo,normal,rough}.jpg (generated by tools/texgen.py).
import React, {createContext, useContext, useEffect, useLayoutEffect, useMemo, useState} from 'react';
import {continueRender, delayRender, staticFile} from 'remotion';
import {useThree} from '@react-three/fiber';
import * as THREE from 'three';
import {RGBELoader} from 'three/examples/jsm/loaders/RGBELoader.js';

export type TexName =
  | 'asphalt' | 'bark' | 'brick_red' | 'castle_stone' | 'cobblestones' | 'concrete' | 'concrete_formed' | 'dirt'
  | 'granite_blocks' | 'grass' | 'gravel' | 'iron_dark' | 'limestone_ashlar' | 'linen' | 'mud_brick' | 'plaster_ochre'
  | 'plaster_white' | 'roman_brick' | 'roof_tiles' | 'rubble_core' | 'rubble_wall' | 'sand' | 'sandstone_blocks'
  | 'snow' | 'steel' | 'steel_painted_red' | 'steel_rusty' | 'stone_face_grey' | 'stone_face_lime' | 'stone_face_sand'
  | 'stone_face_tuff' | 'tuff_blocks' | 'water' | 'wood_oak' | 'wood_pine' | 'tuff_carved' | 'tuff_strata' | 'straw'
  | 'ice' | 'mud_plaster' | 'cracked_earth' | 'lagoon_mud' | 'caranto' | 'end_grain' | 'istrian_stone';

type TexSet = {map: THREE.Texture; normalMap: THREE.Texture; roughnessMap: THREE.Texture};

// ---------------------------------------------------------------- loading
const texCache = new Map<string, Promise<THREE.Texture>>();
const loadTexture = (url: string, srgb: boolean) => {
  const key = url + srgb;
  if (!texCache.has(key)) {
    texCache.set(
      key,
      new Promise((res, rej) =>
        new THREE.TextureLoader().load(
          url,
          (t) => {
            t.wrapS = t.wrapT = THREE.RepeatWrapping;
            t.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
            t.anisotropy = 8;
            res(t);
          },
          undefined,
          rej,
        ),
      ),
    );
  }
  return texCache.get(key)!;
};
const hdrCache = new Map<string, Promise<THREE.DataTexture>>();
const loadHdr = (name: string) => {
  if (!hdrCache.has(name)) {
    hdrCache.set(
      name,
      new Promise((res, rej) =>
        new RGBELoader().load(staticFile(`hdri/${name}.hdr`), (t) => {
          t.mapping = THREE.EquirectangularReflectionMapping;
          res(t);
        }, undefined, rej),
      ),
    );
  }
  return hdrCache.get(name)!;
};

type Lib = {tex: Record<string, TexSet>; hdr: THREE.DataTexture | null};
const LibCtx = createContext<Lib | null>(null);

/**
 * Put this INSIDE <ThreeCanvas>. Loads the listed texture sets + HDRI, blocks rendering until ready.
 * Children are rendered only once everything is loaded.
 */
export const AssetProvider: React.FC<{textures: TexName[]; hdri?: string; children: React.ReactNode}> = ({textures, hdri, children}) => {
  const [lib, setLib] = useState<Lib | null>(null);
  const [handle] = useState(() => delayRender('Loading textures'));
  const key = textures.join(',') + '|' + hdri;
  useEffect(() => {
    let alive = true;
    (async () => {
      const tex: Record<string, TexSet> = {};
      await Promise.all(
        textures.map(async (n) => {
          const [map, normalMap, roughnessMap] = await Promise.all([
            loadTexture(staticFile(`tex/${n}/albedo.jpg`), true),
            loadTexture(staticFile(`tex/${n}/normal.jpg`), false),
            loadTexture(staticFile(`tex/${n}/rough.jpg`), false),
          ]);
          tex[n] = {map, normalMap, roughnessMap};
        }),
      );
      const hdr = hdri ? await loadHdr(hdri) : null;
      if (alive) setLib({tex, hdr});
    })().catch((e) => {
      console.error('asset load failed', e);
      continueRender(handle);
    });
    return () => {
      alive = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key]);
  if (!lib) return null;
  return (
    <LibCtx.Provider value={lib}>
      {children}
      <ReadySignal handle={handle} />
    </LibCtx.Provider>
  );
};

/** After the loaded scene mounts, force one GL frame, then let Remotion screenshot. */
const ReadySignal: React.FC<{handle: number}> = ({handle}) => {
  const {advance} = useThree();
  useLayoutEffect(() => {
    const id = requestAnimationFrame(() => {
      advance(performance.now());
      continueRender(handle);
    });
    return () => cancelAnimationFrame(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  return null;
};

const useLib = () => {
  const l = useContext(LibCtx);
  if (!l) throw new Error('useMat must be used inside <AssetProvider>');
  return l;
};

const cloneWithRepeat = (t: THREE.Texture, rx: number, ry: number, rot = 0) => {
  const c = t.clone();
  c.repeat.set(rx, ry);
  c.rotation = rot;
  c.needsUpdate = true;
  return c;
};

export type MatOpts = {
  /** texture repeats across 0..1 UV (use uvBox/worldUV geometry and keep this 1 for world-scaled UVs) */
  repeat?: [number, number];
  rotation?: number;
  tint?: string;
  roughness?: number;
  metalness?: number;
  normalScale?: number;
  envMapIntensity?: number;
  transparent?: boolean;
  opacity?: number;
  side?: THREE.Side;
  emissive?: string;
  emissiveIntensity?: number;
  clip?: THREE.Plane[];
};

/** Memoized textured MeshStandardMaterial. */
export const useMat = (name: TexName, o: MatOpts = {}) => {
  const lib = useLib();
  const set = lib.tex[name];
  const k = JSON.stringify({...o, clip: undefined});
  return useMemo(() => {
    if (!set) throw new Error(`texture "${name}" not listed in AssetProvider`);
    const [rx, ry] = o.repeat ?? [1, 1];
    const m = new THREE.MeshStandardMaterial({
      map: cloneWithRepeat(set.map, rx, ry, o.rotation),
      normalMap: cloneWithRepeat(set.normalMap, rx, ry, o.rotation),
      roughnessMap: cloneWithRepeat(set.roughnessMap, rx, ry, o.rotation),
      normalScale: new THREE.Vector2(o.normalScale ?? 1, o.normalScale ?? 1),
      roughness: o.roughness ?? 1,
      metalness: o.metalness ?? 0,
      color: new THREE.Color(o.tint ?? '#ffffff'),
      envMapIntensity: o.envMapIntensity ?? 1,
      transparent: o.transparent ?? false,
      opacity: o.opacity ?? 1,
      side: o.side ?? THREE.FrontSide,
      emissive: new THREE.Color(o.emissive ?? '#000000'),
      emissiveIntensity: o.emissiveIntensity ?? 0,
    });
    if (o.clip) m.clippingPlanes = o.clip;
    return m;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [set, k, o.clip]);
};

/** Plain (untextured) PBR material, memoized. */
export const usePlainMat = (color: string, roughness = 0.7, metalness = 0, extra: Partial<THREE.MeshStandardMaterialParameters> = {}) =>
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useMemo(() => new THREE.MeshStandardMaterial({color, roughness, metalness, ...extra}), [color, roughness, metalness, JSON.stringify(extra)]);

// ---------------------------------------------------------------- geometry with world-scaled UVs
/** Box whose UVs are in world units / texScale, so textures keep a constant size on any box. */
export const uvBox = (w: number, h: number, d: number, texScale = 1, seg: [number, number, number] = [1, 1, 1]) => {
  const g = new THREE.BoxGeometry(w, h, d, ...seg);
  const uv = g.getAttribute('uv') as THREE.BufferAttribute;
  const nrm = g.getAttribute('normal') as THREE.BufferAttribute;
  for (let i = 0; i < uv.count; i++) {
    const nx = Math.abs(nrm.getX(i)), ny = Math.abs(nrm.getY(i));
    const [du, dv] = nx > 0.5 ? [d, h] : ny > 0.5 ? [w, d] : [w, h];
    uv.setXY(i, (uv.getX(i) * du) / texScale, (uv.getY(i) * dv) / texScale);
  }
  uv.needsUpdate = true;
  return g;
};

/** Re-map any geometry's UVs by triplanar-ish projection of positions (box mapping) in world units / texScale. */
export const worldUV = (g: THREE.BufferGeometry, texScale = 1) => {
  const pos = g.getAttribute('position') as THREE.BufferAttribute;
  if (!g.getAttribute('normal')) g.computeVertexNormals();
  const nrm = g.getAttribute('normal') as THREE.BufferAttribute;
  const uvs = new Float32Array(pos.count * 2);
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), y = pos.getY(i), z = pos.getZ(i);
    const ax = Math.abs(nrm.getX(i)), ay = Math.abs(nrm.getY(i)), az = Math.abs(nrm.getZ(i));
    let u, v;
    if (ay >= ax && ay >= az) [u, v] = [x, z];
    else if (ax >= az) [u, v] = [z, y];
    else [u, v] = [x, y];
    uvs[i * 2] = u / texScale;
    uvs[i * 2 + 1] = v / texScale;
  }
  g.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));
  return g;
};

/** Hook version of uvBox (memoized). */
export const useUvBox = (w: number, h: number, d: number, texScale = 1) => useMemo(() => uvBox(w, h, d, texScale), [w, h, d, texScale]);

// ---------------------------------------------------------------- renderer / lighting
/** Tone mapping, soft shadows, clipping, HDRI environment lighting. Put inside AssetProvider. */
export const Renderer: React.FC<{exposure?: number; envIntensity?: number; envRotation?: number}> = ({exposure = 1.0, envIntensity = 0.6, envRotation = 0}) => {
  const {gl, scene} = useThree();
  const lib = useLib();
  useLayoutEffect(() => {
    gl.toneMapping = THREE.ACESFilmicToneMapping;
    gl.toneMappingExposure = exposure;
    gl.outputColorSpace = THREE.SRGBColorSpace;
    gl.shadowMap.enabled = true;
    gl.shadowMap.type = THREE.PCFSoftShadowMap;
    gl.localClippingEnabled = true;
    if (lib.hdr) {
      scene.environment = lib.hdr;
      scene.environmentIntensity = envIntensity;
      scene.environmentRotation.set(0, envRotation, 0);
    }
  }, [gl, scene, lib.hdr, exposure, envIntensity, envRotation]);
  return null;
};

/** Sun (directional, soft shadows) + sky/ground hemisphere fill. */
export const Sun: React.FC<{
  dir?: [number, number, number];
  intensity?: number;
  color?: string;
  shadowSize?: number;
  shadowRes?: number;
  target?: [number, number, number];
  skyColor?: string;
  groundColor?: string;
  hemi?: number;
}> = ({dir = [-0.6, 1, 0.5], intensity = 3.2, color = '#fff1dc', shadowSize = 40, shadowRes = 2048, target = [0, 0, 0], skyColor = '#bcd8f5', groundColor = '#a08860', hemi = 0.6}) => {
  const light = useMemo(() => new THREE.DirectionalLight(), []);
  const v = new THREE.Vector3(...dir).normalize().multiplyScalar(80);
  useLayoutEffect(() => {
    light.target.position.set(...target);
    light.target.updateMatrixWorld();
  });
  return (
    <>
      <hemisphereLight args={[skyColor, groundColor, hemi]} />
      <primitive
        object={light}
        position={[v.x + target[0], v.y + target[1], v.z + target[2]]}
        intensity={intensity}
        color={color}
        castShadow
        shadow-mapSize-width={shadowRes}
        shadow-mapSize-height={shadowRes}
        shadow-camera-left={-shadowSize}
        shadow-camera-right={shadowSize}
        shadow-camera-top={shadowSize}
        shadow-camera-bottom={-shadowSize}
        shadow-camera-near={1}
        shadow-camera-far={200}
        shadow-bias={-0.0004}
        shadow-normalBias={0.02}
        shadow-radius={4}
      />
      <primitive object={light.target} />
    </>
  );
};

// ---------------------------------------------------------------- sky dome with sun glow + soft clouds
const skyVert = /* glsl */ `
varying vec3 vDir;
void main(){ vDir = normalize(position); vec4 p = modelViewMatrix * vec4(position,1.0); gl_Position = projectionMatrix * p; gl_Position.z = gl_Position.w; }`;
const skyFrag = /* glsl */ `
uniform vec3 top; uniform vec3 horizon; uniform vec3 bottom; uniform vec3 sunDir; uniform vec3 sunColor; uniform float cloudAmt; uniform float time;
varying vec3 vDir;
float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1,311.7))) * 43758.5453); }
float noise(vec2 p){ vec2 i=floor(p), f=fract(p); f=f*f*(3.0-2.0*f);
  return mix(mix(hash(i),hash(i+vec2(1,0)),f.x), mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x), f.y); }
float fbm(vec2 p){ float a=0.5, s=0.0; for(int i=0;i<5;i++){ s+=a*noise(p); p*=2.03; a*=0.5; } return s; }
void main(){
  vec3 d = normalize(vDir);
  float h = d.y;
  vec3 col = h > 0.0 ? mix(horizon, top, pow(clamp(h,0.0,1.0), 0.32)) : mix(horizon, bottom, clamp(-h*4.0,0.0,1.0));
  float sd = max(dot(d, normalize(sunDir)), 0.0);
  col += sunColor * (pow(sd, 900.0) * 6.0 + pow(sd, 18.0) * 0.35);
  if (h > 0.0 && cloudAmt > 0.0) {
    vec2 uv = d.xz / (h + 0.12) * 1.4 + vec2(time * 0.01, 0.0);
    float c = smoothstep(0.78 - cloudAmt * 0.3, 0.95, fbm(uv));
    float lit = 0.85 + 0.15 * pow(sd, 4.0);
    col = mix(col, vec3(1.0, 0.99, 0.97) * lit, c * smoothstep(0.0, 0.18, h) * 0.9);
  }
  gl_FragColor = vec4(col, 1.0);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}`;

export const SkyDome: React.FC<{
  top?: string; horizon?: string; bottom?: string; sunDir?: [number, number, number]; sunColor?: string; clouds?: number; time?: number;
}> = ({top = '#1f5bb5', horizon = '#a9cbec', bottom = '#b9a988', sunDir = [-0.6, 1, 0.5], sunColor = '#fff2d8', clouds = 0.5, time = 0}) => {
  const mat = useMemo(
    () =>
      new THREE.ShaderMaterial({
        vertexShader: skyVert,
        fragmentShader: skyFrag,
        side: THREE.BackSide,
        depthWrite: false,
        uniforms: {
          top: {value: new THREE.Color()}, horizon: {value: new THREE.Color()}, bottom: {value: new THREE.Color()},
          sunDir: {value: new THREE.Vector3()}, sunColor: {value: new THREE.Color()}, cloudAmt: {value: 0}, time: {value: 0},
        },
      }),
    [],
  );
  mat.uniforms.top.value.set(top);
  mat.uniforms.horizon.value.set(horizon);
  mat.uniforms.bottom.value.set(bottom);
  mat.uniforms.sunDir.value.set(...sunDir);
  mat.uniforms.sunColor.value.set(sunColor);
  mat.uniforms.cloudAmt.value = clouds;
  mat.uniforms.time.value = time;
  const {camera} = useThree();
  return (
    <mesh material={mat} position={camera.position} renderOrder={-1} frustumCulled={false}>
      <sphereGeometry args={[400, 32, 16]} />
    </mesh>
  );
};

/** Big textured ground with large-scale colour variation (hides tiling). `texScale` = metres per texture tile. */
export const Ground: React.FC<{tex: TexName; size?: number; texScale?: number; tint?: string; y?: number; normalScale?: number; macro?: number}> = ({
  tex, size = 800, texScale = 6, tint, y = 0, normalScale = 1, macro = 0.35,
}) => {
  const base = useMat(tex, {repeat: [size / texScale, size / texScale], tint, normalScale});
  const m = useMemo(() => {
    const mm = base.clone();
    mm.onBeforeCompile = (sh) => {
      sh.uniforms.macroAmt = {value: macro};
      sh.vertexShader = sh.vertexShader
        .replace('#include <common>', '#include <common>\nvarying vec2 vGPos;')
        .replace('#include <begin_vertex>', '#include <begin_vertex>\nvGPos = (modelMatrix * vec4(position,1.0)).xz;');
      sh.fragmentShader = sh.fragmentShader
        .replace('#include <common>', `#include <common>
varying vec2 vGPos; uniform float macroAmt;
float gh(vec2 p){ return fract(sin(dot(p, vec2(127.1,311.7))) * 43758.5453); }
float gn(vec2 p){ vec2 i=floor(p), f=fract(p); f=f*f*(3.0-2.0*f);
  return mix(mix(gh(i),gh(i+vec2(1,0)),f.x), mix(gh(i+vec2(0,1)),gh(i+vec2(1,1)),f.x), f.y); }`)
        .replace('#include <map_fragment>', `#include <map_fragment>
float mv = gn(vGPos / 23.0) * 0.6 + gn(vGPos / 61.0) * 0.4;
diffuseColor.rgb *= mix(1.0, 0.72 + 0.56 * mv, macroAmt);`);
    };
    mm.customProgramCacheKey = () => 'groundMacro' + macro;
    return mm;
  }, [base, macro]);
  return (
    <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, y, 0]} receiveShadow material={m}>
      <planeGeometry args={[size, size]} />
    </mesh>
  );
};

/** Ground patch blended over the base ground (e.g. dirt work-site, path). Soft edge via alphaMap. */
export const GroundPatch: React.FC<{tex: TexName; w: number; d: number; position?: [number, number, number]; rotY?: number; texScale?: number; tint?: string}> = ({
  tex, w, d, position = [0, 0, 0], rotY = 0, texScale = 4, tint,
}) => {
  const base = useMat(tex, {repeat: [w / texScale, d / texScale], tint});
  const alpha = useMemo(() => {
    const c = document.createElement('canvas');
    c.width = c.height = 128;
    const x = c.getContext('2d')!;
    const g = x.createRadialGradient(64, 64, 20, 64, 64, 64);
    g.addColorStop(0, '#fff');
    g.addColorStop(0.7, '#fff');
    g.addColorStop(1, '#000');
    x.fillStyle = g;
    x.fillRect(0, 0, 128, 128);
    return new THREE.CanvasTexture(c);
  }, []);
  const m = useMemo(() => {
    const mm = base.clone();
    mm.alphaMap = alpha;
    mm.transparent = true;
    mm.depthWrite = false;
    mm.polygonOffset = true;
    mm.polygonOffsetFactor = -2;
    return mm;
  }, [base, alpha]);
  return (
    <mesh rotation={[-Math.PI / 2, 0, rotY]} position={[position[0], position[1] + 0.02, position[2]]} receiveShadow material={m}>
      <planeGeometry args={[w, d]} />
    </mesh>
  );
};
